#!/usr/bin/env node
/**
 * gen-backlog-tasks.mjs — BACKLOG.md → lib/tasks/backlog.tasks.json
 *
 * Precomputes the parsed rows at build time so the /api/tasks-import serverless
 * function can `import` them (esbuild inlines the JSON into the function bundle)
 * with no runtime filesystem read on Vercel. Regenerated by ensure-ops-data on
 * every build/typecheck, so it never drifts from BACKLOG.md.
 */

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseBacklog } from '../lib/tasks/backlog.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = resolve(ROOT, 'lib/tasks/backlog.tasks.json');

const md = readFileSync(resolve(ROOT, 'BACKLOG.md'), 'utf8');
const rows = parseBacklog(md);
mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, `${JSON.stringify(rows, null, 2)}\n`);
console.log(`[gen-backlog-tasks] wrote ${rows.length} rows → lib/tasks/backlog.tasks.json`);
